package org.apache.commons.math3.genetics;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NullArgumentException;
import org.apache.commons.math3.exception.NumberIsTooLargeException;
import org.apache.commons.math3.exception.NumberIsTooSmallException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.mock;

/**
 * Unit tests for ListPopulation.addChromosome.
 */
public class ListPopulation_addChromosome_TriageGen2Test {

    @Test
    public void testAddChromosome_Success() {
        int limit = 5;
        ListPopulation population = new ListPopulation(limit);
        Chromosome chromosome = mock(Chromosome.class);

        population.addChromosome(chromosome);

        Assert.assertEquals(1, population.getPopulationSize());
        Assert.assertTrue(population.getChromosomes().contains(chromosome));
    }

    @Test
    public void testAddChromosome_MultipleSuccess() {
        int limit = 3;
        ListPopulation population = new ListPopulation(limit);
        Chromosome c1 = mock(Chromosome.class);
        Chromosome c2 = mock(Chromosome.class);

        population.addChromosome(c1);
        population.addChromosome(c2);

        Assert.assertEquals(2, population.getPopulationSize());
        Assert.assertEquals(c1, population.getChromosomes().get(0));
        Assert.assertEquals(c2, population.getChromosomes().get(1));
    }

    @Test(expected = NumberIsTooLargeException.class)
    public void testAddChromosome_ThrowsExceptionWhenLimitReached() {
        int limit = 1;
        ListPopulation population = new ListPopulation(limit);
        Chromosome c1 = mock(Chromosome.class);
        Chromosome c2 = mock(Chromosome.class);

        // First addition should succeed
        population.addChromosome(c1);

        // Second addition should trigger the exception because size (1) >= limit (1)
        population.addChromosome(c2);
    }

    @Test
    public void testAddChromosome_WithExistingList() {
        int limit = 10;
        List<Chromosome> initialList = new ArrayList<>();
        Chromosome c1 = mock(Chromosome.class);
        initialList.add(c1);

        ListPopulation population = new ListPopulation(initialList, limit);
        Chromosome c2 = mock(Chromosome.class);

        population.addChromosome(c2);

        Assert.assertEquals(2, population.getPopulationSize());
        Assert.assertEquals(c2, population.getChromosomes().get(1));
    }

    @Test(expected = NumberIsTooLargeException.class)
    public void testAddChromosome_WithPreFilledListAtLimit() {
        int limit = 2;
        List<Chromosome> initialList = new ArrayList<>();
        initialList.add(mock(Chromosome.class));
        initialList.add(mock(Chromosome.class));

        ListPopulation population = new ListPopulation(initialList, limit);
        Chromosome c3 = mock(Chromosome.class);

        // Size is already 2, which is >= limit 2
        population.addChromosome(c3);
    }
}
